--
-- Resource recycling per-capita seed data
-- Source: dataset-analysis/eco-friendly/執行機關資源回收量.csv
--

DROP TABLE IF EXISTS public.resource_recycling_amounts;
DROP TABLE IF EXISTS public.county_resident_population_109;

CREATE TABLE public.county_resident_population_109 (
    county_city text PRIMARY KEY,
    resident_population integer NOT NULL
);

CREATE TABLE public.resource_recycling_amounts (
    stat_year integer NOT NULL,
    stat_month integer,
    period text NOT NULL,
    county_city text NOT NULL,
    category text NOT NULL,
    amount_ton double precision NOT NULL
);



CREATE INDEX resource_recycling_amounts_year_month_city_idx
ON public.resource_recycling_amounts (stat_year, stat_month, county_city);

CREATE INDEX resource_recycling_amounts_period_city_idx
ON public.resource_recycling_amounts (period, county_city);
